export function getBreedImage(slugOrPet) {
  if (!slugOrPet) return null;
  const slug = typeof slugOrPet === 'string' ? slugOrPet : slugOrPet.slug;
  if (slug && BREED_IMAGES[slug]) return BREED_IMAGES[slug];
  if (typeof slugOrPet === 'object' && slugOrPet.image_url) return slugOrPet.image_url;
  return null;
}
